# module4 robustness: evaluate AUROC for top3 ATAC embedding stress runs
# -----------------------------------------------------------------------------
# Purpose:
#   Evaluate all TRS outputs generated by:
#
#     05_robustness/02_run_top3_embedding_stress.R
#
# Reuses:
#   04_evaluation/eval_auroc.R
#
# Targets:
#   MONO -> CD14 mono ATAC proxy
#   RDW  -> red-lineage ATAC proxy
#   RBC  -> red-lineage ATAC proxy
#
# Cell type is used only here, for post hoc AUROC evaluation.
#
# Run in RStudio:
#   setwd("D:/RStudio/work/module4_traitaware_pseudopair")
#   source("05_robustness/03_evaluate_top3_embedding_stress.R")
# -----------------------------------------------------------------------------

suppressPackageStartupMessages({
  library(data.table)
})

ROOT <- "D:/RStudio/work/module4_traitaware_pseudopair"
ROBUST_DIR <- file.path(ROOT, "05_robustness/output/top3_embedding_stress")
RUNS_DIR <- file.path(ROBUST_DIR, "runs")
EVAL_DIR <- file.path(ROBUST_DIR, "eval")
dir.create(EVAL_DIR, recursive = TRUE, showWarnings = FALSE)

BASE_EVAL_SCRIPT <- file.path(ROOT, "04_evaluation/eval_auroc.R")
OUT_ALL <- file.path(ROBUST_DIR, "top3_embedding_stress_auroc_all.csv")

if (!exists("BOOTSTRAP_CI_ROBUST")) BOOTSTRAP_CI_ROBUST <- FALSE

TARGET_REPLACEMENT <- c(
  'TARGETS <- list(',
  '  MONO = c("11_CD14.Mono.1", "12_CD14.Mono.2"),',
  '  RDW = c("02_Early.Eryth", "03_Late.Eryth", "04_Early.Baso"),',
  '  RBC = c("02_Early.Eryth", "03_Late.Eryth", "04_Early.Baso")',
  ')'
)
PRED_REPLACEMENT <- c(
  'PRED_TRAIT <- list(MONO = "MONO", RDW = "RDW", RBC = "RBC")',
  ''
)

stop_missing <- function(paths) {
  missing <- paths[!file.exists(paths)]
  if (length(missing) > 0L) {
    stop("Missing required file(s):\n  ", paste(missing, collapse = "\n  "),
         call. = FALSE)
  }
}

parse_run_id <- function(run_id) {
  m <- regmatches(run_id, regexec("^noise([0-9]+)p([0-9]+)_seed([0-9]+)$", run_id))[[1]]
  if (length(m) != 4L) {
    return(data.table(noise_sd = NA_real_, stress_seed = NA_integer_))
  }
  data.table(
    noise_sd = as.numeric(paste0(m[2], ".", m[3])),
    stress_seed = as.integer(m[4])
  )
}

patch_eval_script <- function(in_file, out_file, v2_dir, out_dir, out_csv_name) {
  txt <- readLines(in_file, warn = FALSE)

  txt <- sub(
    "^V2_FILES_DIR\\s*<-.*$",
    paste0('V2_FILES_DIR <- "', normalizePath(v2_dir, winslash = "/", mustWork = TRUE), '"'),
    txt
  )
  txt <- sub(
    "^OUT_DIR\\s*<-.*$",
    paste0('OUT_DIR <- "', normalizePath(out_dir, winslash = "/", mustWork = TRUE), '"'),
    txt
  )
  txt <- sub(
    "^OUT_CSV_NAME\\s*<-.*$",
    paste0('OUT_CSV_NAME <- "', out_csv_name, '"'),
    txt
  )
  txt <- sub(
    "^BOOTSTRAP_CI\\s*<-.*$",
    paste0("BOOTSTRAP_CI <- ", ifelse(BOOTSTRAP_CI_ROBUST, "TRUE", "FALSE")),
    txt
  )

  target_start <- grep("^TARGETS\\s*<-\\s*list\\(", txt)[1]
  pred_start <- grep("^PRED_TRAIT\\s*<-\\s*list\\(", txt)[1]
  if (is.na(target_start) || is.na(pred_start) || pred_start <= target_start) {
    stop("Could not locate TARGETS/PRED_TRAIT blocks in eval script.", call. = FALSE)
  }
  txt <- c(
    txt[seq_len(target_start - 1L)],
    TARGET_REPLACEMENT,
    txt[pred_start:length(txt)]
  )

  pred_start <- grep("^PRED_TRAIT\\s*<-\\s*list\\(", txt)[1]
  boot_start <- grep("^BOOTSTRAP_CI\\s*<-", txt)[1]
  if (is.na(pred_start) || is.na(boot_start) || boot_start <= pred_start) {
    stop("Could not locate PRED_TRAIT block in eval script.", call. = FALSE)
  }
  txt <- c(
    txt[seq_len(pred_start - 1L)],
    PRED_REPLACEMENT,
    txt[boot_start:length(txt)]
  )

  writeLines(txt, out_file, useBytes = TRUE)
  out_file
}

cat(">>> Evaluate top3 ATAC embedding stress robustness\n\n")
cat("Runs dir: ", RUNS_DIR, "\n", sep = "")
cat("Eval dir: ", EVAL_DIR, "\n", sep = "")
cat("BOOTSTRAP_CI_ROBUST = ", BOOTSTRAP_CI_ROBUST, "\n\n", sep = "")

stop_missing(BASE_EVAL_SCRIPT)

run_dirs <- list.dirs(RUNS_DIR, recursive = FALSE, full.names = TRUE)
run_dirs <- run_dirs[file.exists(file.path(run_dirs, "trs_summary_v2.csv"))]
if (length(run_dirs) == 0L) {
  stop("No completed robustness run directories found in: ", RUNS_DIR,
       call. = FALSE)
}

all_rows <- list()
for (run_dir in run_dirs) {
  run_id <- basename(run_dir)
  cat("=== Evaluating ", run_id, " ===\n", sep = "")
  run_eval_dir <- file.path(EVAL_DIR, run_id)
  dir.create(run_eval_dir, recursive = TRUE, showWarnings = FALSE)
  out_csv_name <- paste0(run_id, "_auroc.csv")
  patched <- file.path(run_eval_dir, paste0("eval_auroc.", run_id, ".patched.R"))

  patch_eval_script(
    in_file = BASE_EVAL_SCRIPT,
    out_file = patched,
    v2_dir = run_dir,
    out_dir = run_eval_dir,
    out_csv_name = out_csv_name
  )
  source(patched, local = new.env(parent = globalenv()))

  one <- fread(file.path(run_eval_dir, out_csv_name))
  meta <- parse_run_id(run_id)
  one[, `:=`(
    run_id = run_id,
    noise_sd = meta$noise_sd,
    stress_seed = meta$stress_seed
  )]
  all_rows[[run_id]] <- one
}

all_dt <- rbindlist(all_rows, use.names = TRUE, fill = TRUE)
setcolorder(all_dt, c("run_id", "noise_sd", "stress_seed"))
fwrite(all_dt, OUT_ALL)

cat("\n=== Robustness AUROC evaluation finished ===\n")
cat("Wrote: ", OUT_ALL, "\n", sep = "")
